insert into public.journal_articles (status, author_type, author_name, image_rights, review, related_products, cta_type, sources, id, group_key, content_id, language, market, slug, title, dek, hero_image_url, hero_image_alt, hero_image_caption, hero_image_credit, seo_title, seo_description, body_md)
values ('in_review', 'hondit_editorial', 'HONDIT editorial team', 'confirmed', '{"facts":true,"claims":true,"images":true,"notes":"2026-11-12: 사실은 JOURNAL_FACTS·주문 조건 기준, 위험 표현 자동 검사 통과, 사진은 StoneJeju 사용 허락 범위(JW 확인). 가격 수치는 본문에 넣지 않음.","reviewer":"HONDIT editorial","reviewed_at":"2026-11-12T00:00:00Z"}'::jsonb, array['diffuser-350g','diffuser-500g']::text[], 'product', '[{"label":"StoneJeju 볼카닉 디퓨져 350","url":"https://stonejeju.com/product/detail.html?product_no=42"},{"label":"StoneJeju 볼카닉 디퓨져 500","url":"https://stonejeju.com/product/detail.html?product_no=41"},{"label":"HONDIT 상품 관리 안내","url":"https://hondit-shop.vercel.app/products/diffuser-350g"},{"label":"HONDIT 무료 PR 기사 초안 (2026-10-23)","url":"https://docs.google.com/document/d/14ARAH6CKJbRcPKNeO87GMq6BBOyD_bxTLiPuJaVzHRg/edit"}]'::jsonb, '7d1f0f0a-0003-4a10-9a01-000000000001', 'stone-vs-reed-vs-electric-2026-11', 'S-JRN-SG-03', 'en', 'SG', 'stone-diffuser-vs-reed-vs-electric', 'Stone, reed or electric? How a volcanic-stone diffuser is different', 'A stone diffuser, also called an aroma stone or lava stone diffuser, works differently from a reed diffuser or an electric one. Here is what you set up, what you need and what you refill, using StoneJeju''s Jeju scoria diffuser as the example.', '/images/hondit-pack/hondit_codex_image_pack/01_product_originals/08_diffuser_500_wood.webp', 'StoneJeju Volcanic Diffuser 500g: Jeju scoria in a Jeju onggi pot on a wooden shelf, with its box and bottle of citrus fragrance oil', 'A stone diffuser is the stone, a vessel and a bottle of oil.', 'Photo: StoneJeju official product photograph. Used with permission.', 'Stone diffuser vs reed vs electric: what is the difference? | HONDIT Journal', 'How an aroma stone (lava stone diffuser) differs from a reed diffuser and an electric diffuser: set-up, what you refill and what it needs. Example: StoneJeju''s Jeju volcanic scoria diffuser.', 'Home fragrance comes in three common forms: a bottle with reeds, a plug-in or rechargeable electric diffuser, and a porous stone that you scent with a few drops of oil. They solve the same small problem in different ways, so it helps to know what each one asks of you before choosing.

## Three ways to scent a room

- Reed diffuser: a bottle of fragrance liquid with sticks standing in it. The liquid travels up the sticks. You top it up or replace the bottle when it runs low.
- Electric diffuser: a unit that uses power to spread fragrance, often with water or oil inside. It needs a socket or a charged battery, and it needs cleaning.
- Stone diffuser (aroma stone): a porous stone that takes up fragrance oil and gives it off slowly. There is no liquid bottle to knock over, no stick to replace and no cable.

## What a lava stone diffuser is made of

The stone in StoneJeju''s diffuser is Jeju volcanic scoria, called songi in Korean. It formed from lava on Jeju Island and is full of tiny holes, which is why people also call this kind of object a lava stone or lava rock diffuser. The holes are what hold the oil.

![A hand picking up red-brown volcanic scoria on Jeju](/images/journal/material-jeju-scoria.webp "Jeju scoria: a porous volcanic rock. Photo: StoneJeju, used with permission.")

## How it is used

Place the stone in its vessel and add 10–12 drops of the citrus oil across the upper stones. Add a few drops again whenever you want the scent back. Each set comes with 10mL of citrus fragrance oil, so there is nothing to buy to start.

## What it needs, side by side

- Power: stone none, reed none, electric yes.
- Flame: stone none, reed none, electric none.
- Reeds or sticks to replace: stone no, reed yes, electric no.
- Water or a tank to clean: stone no, reed no, electric usually.
- How the scent is added: stone by drops when you choose, reed by a bottle that is always open, electric by switching it on.

Because you decide when to add oil, a stone diffuser stays quiet on the days you do not want fragrance.

## Two sizes

- 350g: about 75 × 100 × 75 mm, in a glass vessel. It suits a desk, a bedside table or a small shelf.
- 500g: about 100 × 105 × 100 mm, in Jeju onggi earthenware. It is made for a living room or a shared space.

## Care and variation

The stone is natural, so size and colour vary from set to set and it may shed fine powder. To change fragrance, rinse the stone in warm water and let it dry completely first. Avoid prolonged contact with sensitive or damaged skin and follow the oil''s label.

## Who is behind it

StoneJeju is the maker and the product brand. HONDIT is a student-operated curation team from Jeju National University''s GTEP programme that introduces the diffuser to overseas customers. HONDIT is not the manufacturer.

## Ordering from Singapore

Orders from Singapore can be paid directly for 5, 10 or 20 or more units of one size, with delivery from Korea included in the price on the product page. See the [350g diffuser](/products/diffuser-350g) or the [500g diffuser](/products/diffuser-500g). Other quantities, mixed sizes or a quantity above the stock shown are handled as a quote: [send an enquiry](/contact). Any import duties or taxes are paid by the recipient.')
on conflict (content_id) do nothing;

insert into public.journal_articles (status, author_type, author_name, image_rights, review, related_products, cta_type, sources, id, group_key, content_id, language, market, slug, title, dek, hero_image_url, hero_image_alt, hero_image_caption, hero_image_credit, seo_title, seo_description, body_md)
values ('in_review', 'hondit_editorial', 'HONDIT editorial team', 'confirmed', '{"facts":true,"claims":true,"images":true,"notes":"2026-11-12: 사실은 JOURNAL_FACTS·주문 조건 기준, 위험 표현 자동 검사 통과, 사진은 StoneJeju 사용 허락 범위(JW 확인). 가격 수치는 본문에 넣지 않음.","reviewer":"HONDIT editorial","reviewed_at":"2026-11-12T00:00:00Z"}'::jsonb, array['diffuser-350g','diffuser-500g']::text[], 'product', '[{"label":"StoneJeju 볼카닉 디퓨져 350","url":"https://stonejeju.com/product/detail.html?product_no=42"},{"label":"StoneJeju 볼카닉 디퓨져 500","url":"https://stonejeju.com/product/detail.html?product_no=41"},{"label":"HONDIT 상품 관리 안내","url":"https://hondit-shop.vercel.app/products/diffuser-350g"},{"label":"HONDIT 무료 PR 기사 초안 (2026-10-23)","url":"https://docs.google.com/document/d/14ARAH6CKJbRcPKNeO87GMq6BBOyD_bxTLiPuJaVzHRg/edit"}]'::jsonb, '7d1f0f0a-0003-4a10-9a01-000000000002', 'jeju-non-food-souvenir-2026-11', 'S-JRN-JP-03', 'ja', 'JP', 'jeju-non-food-souvenir-aroma-stone', '食べ物以外の済州島土産を探すなら：火山石のアロマストーン', '済州島のお土産はお菓子や食品が中心です。そのなかで、済州の火山石を使った電気も火も使わないアロマストーン型ディフューザーは、食べ物以外の選択肢になります。大きさや使い方、日本からの注文方法をまとめました。', '/images/hondit-pack/hondit_codex_image_pack/01_product_originals/06_diffuser_500_studio.webp', '済州オンギの器に火山石が入ったStoneJeju火山石ディフューザー500gと、箱、シトラスオイルのボトル', '500gは済州のオンギ（甕器）に火山石を収めています。', '写真：StoneJeju 公式製品写真（許諾を得て使用）', '食べ物以外の済州島お土産｜溶岩石のアロマストーン・電気不要 | HONDIT Journal', '済州島の火山石（溶岩石）を使ったアロマストーン型ディフューザー。電池も電源も火も使わず、食べ物ではないお土産として。350gと500g、日本からのご注文方法。', '済州島のお土産と聞いて思い浮かぶのは、みかんを使ったお菓子や食品という方が多いと思います。おいしいものは旅の楽しみですが、食べてしまえば手元には何も残りません。食べ物以外で、島の空気を持ち帰れるものを探している方に向けて、済州の火山石を使ったディフューザーを紹介します。

## 済州の火山石というお土産

済州島は火山の島で、黒く小さな穴の多い火山石（スコリア）が石垣や海岸のあちこちに見られます。StoneJejuは、この石を器に入れた香りの雑貨をつくっています。石の穴がフレグランスオイルを吸い込み、ゆっくりと香りを広げるため、アロマストーンや溶岩石のディフューザーとも呼ばれるタイプです。電池も電源も要らず、火も使いません。

![済州の赤茶色の火山石を手に取る様子](/images/journal/material-jeju-scoria.webp "済州の火山石（スコリア）。写真：StoneJeju（許諾を得て使用）")

## 贈りものとして考えるとき

- 食べ物ではないので、賞味期限を気にしなくて済みます。
- 電池やコンセントが要らないので、受け取った人は置き場所を選びません。
- 10mLのシトラスオイルが付いているので、受け取ってすぐに使えます。
- 石は天然のため、大きさや色が一つひとつ少しずつ違います。

## 2つのサイズ

- 350g：約75×100×75mm。ガラスの器に石を収めた、デスクや棚に置きやすいサイズです。
- 500g：約100×105×100mm。器は済州のオンギ（甕器）で、玄関やリビングなど少し広い場所に向いています。

## 使い方

石を器に入れ、上の石にシトラスオイルを10〜12滴たらします。香りがほしいときに、数滴足してください。香りの量を自分で決められるので、香りを足さない日は石を飾っておくだけのオブジェになります。

## お手入れ

天然石のため、細かな粉が出ることがあります。別の香りに替えるときは、石をぬるま湯ですすぎ、完全に乾かしてから使ってください。敏感な肌や傷のある肌に長く触れないようにし、オイルの表示に従ってください。

## つくり手と届け手

製品ブランド・製造はStoneJejuです。HONDITは済州大学GTEPの学生チームで、海外のお客様への商品紹介と販売に関するお問い合わせを担当しています（製造元ではありません）。

## 日本でのご注文

済州島に行かなくても、日本から注文できます。1回のご注文につき1サイズ5個、または20個以上であれば、[350gの商品ページ](/products/diffuser-350g)または[500gの商品ページ](/products/diffuser-500g)で円建てのままお支払いいただけます。表示価格には韓国から日本までの配送料が含まれています。

10個のご注文、2つのサイズを組み合わせたご注文、表示在庫を超える数量は個別のお見積もりになります。[お問い合わせ](/contact)からサイズと数量をお知らせください。関税や輸入時の税金がかかる場合は、受取人のご負担となります。')
on conflict (content_id) do nothing;

insert into public.journal_articles (status, author_type, author_name, image_rights, review, related_products, cta_type, sources, id, group_key, content_id, language, market, slug, title, dek, hero_image_url, hero_image_alt, hero_image_caption, hero_image_credit, seo_title, seo_description, body_md)
values ('in_review', 'hondit_editorial', 'HONDIT editorial team', 'confirmed', '{"facts":true,"claims":true,"images":true,"notes":"2026-11-12: 사실은 JOURNAL_FACTS·주문 조건 기준, 위험 표현 자동 검사 통과, 사진은 StoneJeju 사용 허락 범위(JW 확인). 가격 수치는 본문에 넣지 않음.","reviewer":"HONDIT editorial","reviewed_at":"2026-11-12T00:00:00Z"}'::jsonb, array['diffuser-350g','diffuser-500g']::text[], 'product', '[{"label":"StoneJeju 볼카닉 디퓨져 350","url":"https://stonejeju.com/product/detail.html?product_no=42"},{"label":"StoneJeju 볼카닉 디퓨져 500","url":"https://stonejeju.com/product/detail.html?product_no=41"},{"label":"HONDIT 상품 관리 안내","url":"https://hondit-shop.vercel.app/products/diffuser-350g"},{"label":"HONDIT 무료 PR 기사 초안 (2026-10-23)","url":"https://docs.google.com/document/d/14ARAH6CKJbRcPKNeO87GMq6BBOyD_bxTLiPuJaVzHRg/edit"}]'::jsonb, '7d1f0f0a-0003-4a10-9a01-000000000003', 'small-space-no-flame-2026-11', 'S-JRN-HK-03', 'zh-HK', 'HK', 'small-space-no-flame-no-plug-diffuser', '空間不大，香氛也不用插電：濟州火山石擴香石擺哪裏', '家裏地方有限，不想再多一條電線，也不想點火。濟州火山石擴香石只需要一個層架或一角書桌。這篇整理兩款尺寸、實際佔多少位置，以及在香港的訂購方式。', '/images/hondit-pack/hondit_codex_image_pack/01_product_originals/08_diffuser_500_wood.webp', '木架上的 StoneJeju 火山石擴香 500g，濟州甕器內盛着火山石，旁邊是外盒和柑橘香氛油', '500g 的容器是濟州甕器，約 100 × 105 × 100 mm。', '相片：StoneJeju 官方產品相片（已獲授權使用）', '細空間香氛｜無火無插電的濟州火山石擴香石 | HONDIT Journal', '濟州火山石擴香石不用插電、無火、無藤枝，350g 約 75 × 100 × 75 mm，適合書桌、層架與小空間。附 10mL 柑橘香氛油，說明用法、尺寸與香港訂購方式。', '在空間不大的家裏，擺一件東西之前，多數人會先問：要不要插電、會不會佔位、有沒有地方放。擴香石的好處是答案很簡單：不用電線、不用火，只要一個平面。以下用 StoneJeju 的濟州火山石擴香來說明。

## 一塊石，一個容器

擴香裏面是多孔的濟州火山石（火山渣）。石上有很多細孔，可以吸住香氛油，再慢慢把香氣散到空氣裏。不需要插電，也不用點火，沒有藤枝要更換，亦沒有一瓶液體要提防打翻。每套附 10mL 柑橘香氛油。

![濟州火山石擴香 350，黑色玻璃容器內盛滿火山石，旁邊散放着幾塊石頭](/images/journal/sg-01-diffuser-350-vessel.webp "350：玻璃容器，約 75 × 100 × 75 mm。相片：StoneJeju（已獲授權使用）")

## 兩款尺寸，佔多少位置

- 350g：約 75 × 100 × 75 mm，玻璃容器。差不多是一個杯子的大小，放在書桌、床頭或小層架上都不顯眼。
- 500g：約 100 × 105 × 100 mm，濟州甕器容器。適合客廳的矮櫃、鞋櫃上方或工作室的枱面。

## 使用方法

把石放進容器，在上層的石頭上滴 10 至 12 滴柑橘油。想要香氣的時候，再補幾滴。因為由你決定甚麼時候加油，不想要香味的日子，它就只是一件擺在桌上的黑色石頭擺設。

## 放在哪裏

- 書桌：350g 的體積小，不會佔去太多枱面。
- 層架：黑色的火山石配上簡單的容器，放在書旁邊也不突兀。
- 玄關或矮櫃：500g 的甕器質感較明顯，適合放在進門就看得到的位置。

## 保養

天然石的大小和顏色各有不同，可能會有細粉。想換另一種香味時，先用溫水沖洗石頭，完全乾透後再使用。請避免長時間接觸敏感或受損的皮膚，並依照香氛油的標籤使用。

## 誰製造、誰銷售

製造商及產品品牌是 StoneJeju。HONDIT 是濟州大學 GTEP 學生團隊，負責向海外顧客介紹產品及回覆訂購查詢，並非製造商。

## 在香港訂購

每次訂購同一尺寸 5 件或 20 件以上，可在 [350g 產品頁](/products/diffuser-350g)或 [500g 產品頁](/products/diffuser-500g)直接以港元用 PayPal 付款，價格已包含由韓國寄到香港的運費。

10 件、混合兩種尺寸，或超過顯示庫存的數量，會以報價處理，請透過[聯絡我們](/contact)告知尺寸和數量。如有進口稅項，由收件人支付。')
on conflict (content_id) do nothing;

insert into public.journal_articles (status, author_type, author_name, image_rights, review, related_products, cta_type, sources, id, group_key, content_id, language, market, slug, title, dek, hero_image_url, hero_image_alt, hero_image_caption, hero_image_credit, seo_title, seo_description, body_md)
values ('in_review', 'hondit_editorial', 'HONDIT editorial team', 'confirmed', '{"facts":true,"claims":true,"images":true,"notes":"2026-11-12: 사실은 JOURNAL_FACTS·주문 조건 기준, 위험 표현 자동 검사 통과, 사진은 StoneJeju 사용 허락 범위(JW 확인). 가격 수치는 본문에 넣지 않음.","reviewer":"HONDIT editorial","reviewed_at":"2026-11-12T00:00:00Z"}'::jsonb, array['diffuser-350g','diffuser-500g']::text[], 'product', '[{"label":"StoneJeju 볼카닉 디퓨져 350","url":"https://stonejeju.com/product/detail.html?product_no=42"},{"label":"StoneJeju 볼카닉 디퓨져 500","url":"https://stonejeju.com/product/detail.html?product_no=41"},{"label":"HONDIT 상품 관리 안내","url":"https://hondit-shop.vercel.app/products/diffuser-350g"},{"label":"HONDIT 무료 PR 기사 초안 (2026-10-23)","url":"https://docs.google.com/document/d/14ARAH6CKJbRcPKNeO87GMq6BBOyD_bxTLiPuJaVzHRg/edit"}]'::jsonb, '7d1f0f0a-0003-4a10-9a01-000000000004', 'jeju-stone-desk-object-2026-11', 'S-JRN-TW-03', 'zh-TW', 'TW', 'jeju-volcanic-stone-desk-object', '桌面上的一塊濟州：火山石擴香石的擺件質感', '喜歡簡單、有質感的桌面小物的人，可以看看這件黑色火山石擴香石。不需要插電，也不會有一堆說明書，靜靜放在桌上就是一件擺設。這篇整理它的外型、尺寸、使用與保養，以及台灣的訂購方式。', '/images/hondit-pack/hondit_codex_image_pack/01_product_originals/06_diffuser_500_studio.webp', '濟州甕器容器中的 StoneJeju 火山石擴香 500g，旁邊是外盒、柑橘香氛油和兩塊火山石', '500g：濟州甕器容器，約 100 × 105 × 100 mm。', '照片：StoneJeju 官方產品照片（已獲授權使用）', '桌面擺件｜濟州火山石擴香石，無需插電 | HONDIT Journal', '黑色多孔的濟州火山石擴香石，不插電、不點火，350g 約 75 × 100 × 75 mm。當作桌面擺件也合適，附 10mL 柑橘香氛油，說明用法、保養與台灣訂購方式。', '桌面上的東西不必多，但留下來的，最好是看得久也不膩的。濟州火山石擴香石是一件這樣的東西：一塊黑色、佈滿細孔的石頭，加上一個簡單的容器。不點火、不插電，沒有線、沒有開關，放在桌上就是一件擺設。

## 它長什麼樣子

擴香裏面是濟州火山石（火山渣）。石頭是天然的，每一塊的形狀、大小和色澤都有一點不同，這也是它不像工業製品的地方。石上的細孔會吸住香氛油，再慢慢散出香氣。每套附 10mL 柑橘香氛油。

![350 的黑色玻璃容器盛着火山石，旁邊是亞麻布和幾塊石頭](/images/journal/sg-01-diffuser-350-vessel.webp "350：玻璃容器，約 75 × 100 × 75 mm。照片：StoneJeju（已獲授權使用）")

## 兩個尺寸

- 350g：約 75 × 100 × 75 mm，玻璃容器。放在書桌、床頭或書架一角都剛好。
- 500g：約 100 × 105 × 100 mm，濟州甕器容器。甕器的質感比較樸實，適合放在客廳矮櫃或工作室的枱面。

## 使用方法

把石頭放進容器，在上層石頭上滴 10 至 12 滴柑橘油。想要香氣的時候，再補幾滴。香氣由你決定，不想要香味的日子，就只留石頭，把它當成擺件。

## 日常保養

天然石可能會有細粉。想換另一種香氣時，先用溫水把石頭沖洗乾淨，完全晾乾後再使用。請避免長時間接觸敏感或受傷的皮膚，並依照香氛油標籤使用。

## 誰製造、誰銷售

製造商及產品品牌是 StoneJeju。HONDIT 是濟州大學 GTEP 學生團隊，負責向海外顧客介紹產品、回覆訂購詢問，並非製造商。

## 在台灣訂購

每次訂購同一尺寸 5 件或 20 件以上，可以在 [350g 商品頁](/products/diffuser-350g)或 [500g 商品頁](/products/diffuser-500g)直接以新台幣用 PayPal 付款，價格已包含由韓國寄到台灣的運費。

10 件、兩種尺寸混合，或超過顯示庫存的數量，會以報價處理，請透過[聯絡我們](/contact)告訴我們尺寸和數量。如有進口稅費，由收件人負擔。')
on conflict (content_id) do nothing;

